<template><div class="space-y-4"><el-input v-model="message" type="textarea" :rows="5" placeholder="待签名内容"/><el-input v-model="secret" placeholder="密钥" show-password/><el-select v-model="algorithm" class="w-full"><el-option v-for="item in ['SHA-256','SHA-384','SHA-512']" :key="item" :label="item" :value="item"/></el-select><el-button type="primary" size="small" @click="sign">生成签名</el-button><el-input v-if="result" v-model="result" type="textarea" :rows="3" readonly/></div></template>
<script setup lang="ts">import { ref } from 'vue'; const message=ref('');const secret=ref('');const algorithm=ref('SHA-256');const result=ref('');const sign=async()=>{const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(secret.value),{name:'HMAC',hash:algorithm.value},false,['sign']);const data=await crypto.subtle.sign('HMAC',key,new TextEncoder().encode(message.value));result.value=Array.from(new Uint8Array(data)).map(x=>x.toString(16).padStart(2,'0')).join('')}</script>
